 using System.Collections.Generic;
 using System.Reflection;
 using Microsoft.VisualStudio.TestTools.UnitTesting;
 using Contoso.Pricing;

 namespace Contoso.Pricing.Tests;

 [TestClass]
 public sealed class PriceCalculatorTests
 {
     private PriceCalculator _calculator = null!;

     [TestInitialize]
     public void Setup() => _calculator = new PriceCalculator();

     // ── CalculateTotal: DataRow-driven tests ────────────────────────────

     [TestMethod]
     [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
     [DataRow(10.00, 2, 0.0,  20.00,  DisplayName = "Two items, no tax")]
     [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
     [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
     [DataRow(0.00,  5, 0.10, 0.00,   DisplayName = "Zero unit price")]
     [DataRow(99.99, 0, 0.20, 0.00,   DisplayName = "Zero quantity")]
     [DataRow(10.00, 1, 1.0,  20.00,  DisplayName = "100% tax rate")]
     public void CalculateTotal_WithDataRow_ReturnsExpected(
         double unitPrice, int quantity, double taxRate, double expected)
     {
         var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

         Assert.AreEqual((decimal)expected, result);
     }

     // ── CalculateTotal: DynamicData-driven tests ────────────────────────

     public static IEnumerable<object[]> CalculateTotalCases
     {
         get
         {
             yield return new object[] { 15.00m, 4,  0.07m, 64.20m,  "Bulk with 7% tax" };
             yield return new object[] { 100.0m, 1,  0.0m,  100.0m,  "Expensive item, no tax" };
             yield return new object[] { 1.99m,  10, 0.05m, 20.895m, "Low-price high-quantity" };
             yield return new object[] { 0.01m,  1,  0.0m,  0.01m,   "Minimum positive price" };
         }
     }

     [TestMethod]
     [DynamicData(nameof(CalculateTotalCases), DynamicDataDisplayName = nameof(GetCalculateTotalDisplayName))]
     public void CalculateTotal_WithDynamicData_ReturnsExpected(
         decimal unitPrice, int quantity, decimal taxRate, decimal expected, string scenario)
     {
         var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

         Assert.AreEqual(expected, result, $"Failed for scenario: {scenario}");
     }

     public static string GetCalculateTotalDisplayName(MethodInfo methodInfo, object[] data)
         => (string)data[4];

     // ── CalculateTotal: invalid-input tests ─────────────────────────────

     [TestMethod]
     [DataRow(-1.00, 1,  0.10, DisplayName = "Negative unit price")]
     [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity")]
     [DataRow(10.00, 1,  -0.1, DisplayName = "Negative tax rate")]
     [DataRow(10.00, 1,  1.01, DisplayName = "Tax rate above 1")]
     public void CalculateTotal_InvalidInput_Throws(
         double unitPrice, int quantity, double taxRate)
     {
         Assert.ThrowsException<ArgumentOutOfRangeException>(
             () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
     }

     // ── ApplyDiscount: DataRow-driven tests ─────────────────────────────

     [TestMethod]
     [DataRow(100.00, 0.0,   100.00, DisplayName = "No discount")]
     [DataRow(100.00, 10.0,  90.00,  DisplayName = "10% discount")]
     [DataRow(100.00, 50.0,  50.00,  DisplayName = "50% discount")]
     [DataRow(100.00, 100.0, 0.00,   DisplayName = "100% discount (free)")]
     [DataRow(49.99,  25.0,  37.4925, DisplayName = "Fractional result")]
     [DataRow(0.00,   50.0,  0.00,   DisplayName = "Zero price with discount")]
     public void ApplyDiscount_WithDataRow_ReturnsExpected(
         double price, double discountPercent, double expected)
     {
         var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

         Assert.AreEqual((decimal)expected, result);
     }

     // ── ApplyDiscount: DynamicData-driven tests ─────────────────────────

     public static IEnumerable<object[]> ApplyDiscountCases
     {
         get
         {
             yield return new object[] { 200.0m, 15.0m,  170.0m, "15% off $200" };
             yield return new object[] { 9.99m,  33.33m, 6.660333m, "Repeating-decimal discount" };
             yield return new object[] { 1000m,  0.01m,  999.9m, "Tiny discount on large price" };
         }
     }

     [TestMethod]
     [DynamicData(nameof(ApplyDiscountCases), DynamicDataDisplayName = nameof(GetApplyDiscountDisplayName))]
     public void ApplyDiscount_WithDynamicData_ReturnsExpected(
         decimal price, decimal discountPercent, decimal expected, string scenario)
     {
         var result = _calculator.ApplyDiscount(price, discountPercent);

         Assert.AreEqual(expected, result, $"Failed for scenario: {scenario}");
     }

     public static string GetApplyDiscountDisplayName(MethodInfo methodInfo, object[] data)
         => (string)data[3];

     // ── ApplyDiscount: invalid-input tests ──────────────────────────────

     [TestMethod]
     [DataRow(100.00, -1.0,  DisplayName = "Negative discount")]
     [DataRow(100.00, 100.01, DisplayName = "Discount above 100%")]
     public void ApplyDiscount_InvalidInput_Throws(double price, double discountPercent)
     {
         Assert.ThrowsException<ArgumentOutOfRangeException>(
             () => _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent));
     }
 }

